const BW=["Woef","Wuf","Waf","Ruff","Arf","Grr"],KEEP=/^(kg|cm|min|PR|PRs|RGB|Hex|R|G|B|Benji|Benji’s|Settings)$/;
function TB(s){return s.replace(/[A-Za-zÀ-ÿ’']+/g,w=>{if(KEEP.test(w))return w;let h=0;for(const c of w)h=(h*31+c.charCodeAt(0))%97;let b=BW[h%6];if(w.length>7)b+="!";return /^[A-ZÀ-Þ]/.test(w)?b:b.toLowerCase()})}
