async function gunz(b64){const u=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));return await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream("gzip"))).text()}
async function loadLang(c){
if(c=="nl"||c=="bark"){I18.map=null;I18.rx=null;I18.mem.clear();I18.lang=c;return true}
try{if(!I18.keys)I18.keys=JSON.parse(LSRC?await gunz(LSRC.keys):await(await fetch("lang/keys.json")).text());
if(!I18.ok[c])I18.ok[c]=JSON.parse(LSRC?await gunz(LSRC.packs[c]):await(await fetch("lang/"+c+".json")).text());
const P=I18.ok[c],m=new Map();I18.keys.forEach((k,i)=>{if(P[i])m.set(k,P[i])});I18.map=m;I18.lang=c;I18.mem.clear();
const ks=[...m.keys()].filter(k=>k.length>=7).sort((a,b)=>b.length-a.length);
I18.rx=ks.length?new RegExp(ks.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|"),"g"):null;return true}catch(e){I18.map=null;I18.rx=null;I18.lang="nl";return false}}
function tt(s){const t=s.trim();if(!t)return s;const m=I18.map.get(t);if(m)return s.replace(t,m);const mm=t.match(/^([^\p{L}\p{N}]*)(.*?)([^\p{L}\p{N}]*)$/su);if(mm&&(mm[1]||mm[3])&&mm[2]){const m2=I18.map.get(mm[2]);if(m2)return s.replace(t,mm[1]+m2+mm[3])}for(const[re,tp]of PATS){const x=t.match(re);if(x){s=s.replace(t,tp[LI[I18.lang]].replace(/\$(\d)/g,(_,n)=>x[n]));break}}return I18.rx?s.replace(I18.rx,k=>I18.map.get(k)||k):s}
function TT(s){const L=S.lang||"nl";if(L=="nl")return s;if(L=="bark")return TB(s);if(!I18.map||I18.lang!=L)return s;let r=I18.mem.get(s);if(r!==undefined)return r;r=tt(s);if(I18.mem.size>5000)I18.mem.clear();I18.mem.set(s,r);return r}
