async function*lines(st){const dec=new TextDecoder(),rd=st.getReader();let b="";for(;;){const{value,done}=await rd.read();if(done)break;b+=dec.decode(value,{stream:true});let i;while((i=b.indexOf("\n"))>=0){yield b.slice(0,i);b=b.slice(i+1)}}if(b)yield b}
async function zipEntry(file){const tl=Math.min(file.size,70000),tv=new DataView(await file.slice(file.size-tl).arrayBuffer());let e=-1;for(let i=tl-22;i>=0;i--)if(tv.getUint32(i,true)==0x06054b50){e=i;break}if(e<0)throw 0;const cs=tv.getUint32(e+12,true),co=tv.getUint32(e+16,true),cb=await file.slice(co,co+cs).arrayBuffer(),cv2=new DataView(cb),dc=new TextDecoder();let p=0;
while(p+46<=cb.byteLength&&cv2.getUint32(p,true)==0x02014b50){const m=cv2.getUint16(p+10,true),csz=cv2.getUint32(p+20,true),nl=cv2.getUint16(p+28,true),el=cv2.getUint16(p+30,true),cl=cv2.getUint16(p+32,true),lo=cv2.getUint32(p+42,true),nm=dc.decode(new Uint8Array(cb,p+46,nl));
if(/(^|\/)export\.xml$/.test(nm)){const lv=new DataView(await file.slice(lo,lo+30).arrayBuffer()),ds=lo+30+lv.getUint16(26,true)+lv.getUint16(28,true),s=file.slice(ds,ds+csz).stream();return m==8?s.pipeThrough(new DecompressionStream("deflate-raw")):s}p+=46+nl+el+cl}throw 0}
